/**
 * League registry: IPL, WPL and the extra T20 leagues (BBL, WBBL, PSL, SA20, The Hundred men and women, CPL,
 * ILT20, MLC, BPL, LPL). Each league has its teams (names, colours, home grounds with measured conditions) and a
 * RuleSet (squad sizes, overseas limits, season format, playoff bracket, innings format).
 *
 * Teams and rules come from league-defs.ts, generated by packages/ratings/src/analysis/build-league-rosters.py
 * from league_defs.py. Squads live in packages/ratings (league-rosters.ts / league-players.ts). See docs/LEAGUES.md.
 */

import { IPL_TEAMS, WPL_TEAMS, withMeasuredVenue, type TeamConfig } from "./team.js";
import {
  RULE_PRESETS, type ExtraLeagueId, type LeagueType, type RuleSet, type PlayoffFormat, type MatchFormatId,
} from "./rules.js";
import { LEAGUE_DEFS } from "./league-defs.js";

/** Shape of one entry of the generated LEAGUE_DEFS. */
export interface LeagueDefData {
  id: ExtraLeagueId;
  name: string;
  short: string;
  /** Competition name in the venue / toss analysis */
  competition: string;
  gender: "men" | "women";
  homeCountry: string;
  /** Season the squads come from */
  season: string;
  rules: {
    matchesPerTeam: number;
    playoffTeams: number;
    playoffFormat: PlayoffFormat;
    maxOverseasInXI: number;
    maxOverseasInSquad: number;
    minSquadSize: number;
    maxSquadSize: number;
    squadBuilding: "auction" | "draft";
    matchFormat?: MatchFormatId;
  };
  teams: Array<{
    id: string; shortName: string; name: string; city: string;
    primaryColor: string; secondaryColor: string; stadiumName: string;
  }>;
}

export interface LeagueDef {
  id: LeagueType;
  name: string;
  short: string;
  gender: "men" | "women";
  /** A player whose country differs is "overseas" (counts against the overseas limits) */
  homeCountry: string;
  teams: TeamConfig[];
  rules: RuleSet;
  /** Season the shipped squads come from, e.g. "2025/26" */
  season: string;
  /** How the real league builds its squads. The game starts from the real squads and uses auctions unless the Setup page switches to a draft. */
  realSquadBuilding: "auction" | "draft";
}

/**
 * RuleSet.scoringMultiplier for each extra league (IPL = 1, WPL = 0.82): the mild bowler-friendliness the engine applies to
 * dot and wicket rates. The leagues' actual scoring level is fitted separately in venues.ts (LEAGUE_LEVELS).
 */
export const LEAGUE_SCORING_MULTIPLIER: Record<ExtraLeagueId, number> = {
  bbl: 0.9, wbbl: 0.8, psl: 0.95, sa20: 0.9, "hundred-m": 0.92, "hundred-w": 0.78,
  cpl: 0.92, ilt20: 0.9, mlc: 0.95, bpl: 0.88, lpl: 0.97,
};

function buildRules(def: LeagueDefData): RuleSet {
  const r = def.rules;
  const women = def.gender === "women";
  return {
    name: def.name,
    league: def.id,
    leagueName: def.short,
    teamIds: def.teams.map(t => t.id),
    impactPlayer: false,
    // abstract auction budget on the game's scale: about 5 per squad slot for men, 0.67 for women (WPL: 12 / 18)
    salaryCap: women ? Math.round(r.maxSquadSize * 0.67 * 2) / 2 : r.maxSquadSize * 5,
    maxBouncersPerOver: women ? 1 : 2,
    superOverTieBreaker: "repeated-super-over",
    maxOverseasInXI: r.maxOverseasInXI,
    maxOverseasInSquad: r.maxOverseasInSquad,
    maxSquadSize: r.maxSquadSize,
    minSquadSize: r.minSquadSize,
    matchesPerTeam: r.matchesPerTeam,
    playoffTeams: r.playoffTeams,
    playoffFormat: r.playoffFormat,
    scoringMultiplier: LEAGUE_SCORING_MULTIPLIER[def.id],
    injuriesEnabled: true,
    gender: def.gender,
    playerSource: "real",
    // squadBuilding stays unset: season 1 starts from the real squads; the Setup page can switch to a draft
    maxRetentions: Math.min(6, Math.floor(r.maxSquadSize / 3)),
    maxMiniRetentions: r.maxSquadSize,
    ...(r.matchFormat ? { matchFormat: r.matchFormat } : {}),
  };
}

function buildLeague(def: LeagueDefData): LeagueDef {
  return {
    id: def.id,
    name: def.name,
    short: def.short,
    gender: def.gender,
    homeCountry: def.homeCountry,
    season: def.season,
    realSquadBuilding: def.rules.squadBuilding,
    teams: def.teams.map(t => withMeasuredVenue({
      id: t.id, name: t.name, shortName: t.shortName, city: t.city,
      primaryColor: t.primaryColor, secondaryColor: t.secondaryColor, stadiumName: t.stadiumName,
    })),
    rules: buildRules(def),
  };
}

export const EXTRA_LEAGUES: LeagueDef[] = LEAGUE_DEFS.map(buildLeague);

const IPL_LEAGUE: LeagueDef = {
  id: "ipl", name: "Indian Premier League", short: "IPL", gender: "men", homeCountry: "India",
  teams: IPL_TEAMS, rules: RULE_PRESETS.modern2026, season: "2026", realSquadBuilding: "auction",
};
const WPL_LEAGUE: LeagueDef = {
  id: "wpl", name: "Women's Premier League", short: "WPL", gender: "women", homeCountry: "India",
  teams: WPL_TEAMS, rules: RULE_PRESETS.wpl, season: "2025", realSquadBuilding: "auction",
};

/** IPL, WPL, then the extra leagues in menu order. */
export const ALL_LEAGUES: LeagueDef[] = [IPL_LEAGUE, WPL_LEAGUE, ...EXTRA_LEAGUES];

export const LEAGUE_RULE_PRESETS: Record<ExtraLeagueId, RuleSet> = Object.fromEntries(
  EXTRA_LEAGUES.map(l => [l.id, l.rules]),
) as Record<ExtraLeagueId, RuleSet>;

export function getLeague(id: string | undefined): LeagueDef | undefined {
  return ALL_LEAGUES.find(l => l.id === id);
}

/** Team configs of an extra league, or undefined for IPL / WPL / custom rules. */
export function getExtraLeagueTeams(rules: Pick<RuleSet, "league">): TeamConfig[] | undefined {
  return EXTRA_LEAGUES.find(l => l.id === rules.league)?.teams;
}

export function isExtraLeague(rules: Pick<RuleSet, "league">): boolean {
  return EXTRA_LEAGUES.some(l => l.id === rules.league);
}

/** Women's competition (WPL, WBBL, The Hundred women, or custom rules set to women). */
export function isWomenLeague(rules: Pick<RuleSet, "league" | "gender">): boolean {
  return rules.league === "wpl" || rules.gender === "women";
}

/** Is a player of this nationality "overseas" in the league? */
export function isOverseasIn(leagueId: string | undefined, country: string): boolean {
  const league = getLeague(leagueId) ?? IPL_LEAGUE;
  if (league.homeCountry === "England") return country !== "England" && country !== "Wales";
  return country !== league.homeCountry;
}
